dtsPropsFor.Button:
children: React.ReactNode;
  /** solid: white fill, ember on hover · ember: ember fill · outline: hairline on dark */
  variant?: 'solid' | 'ember' | 'outline';
  href?: string;
  /** trailing icon node, e.g. an ArrowUpRight glyph */
  icon?: React.ReactNode;
  className?: string;

dtsPropsFor.Eyebrow:
children: React.ReactNode;
  /** dark: ember on ink · light: ember-deep on paper · onImage: white on the hero/contact gradient */
  tone?: 'dark' | 'light' | 'onImage';

dtsPropsFor.Tag:
children: React.ReactNode;
  /** tech: muted outline on paper · accent-dark: ember on ink · accent-light: ember-deep on paper */
  variant?: 'tech' | 'accent-dark' | 'accent-light';

dtsPropsFor.SectionHeading:
eyebrow: string;
  title: React.ReactNode;
  /** dark: on the ink canvas · light: on the paper band */
  tone?: 'dark' | 'light';
  /** optional supporting line under the heading */
  description?: React.ReactNode;

dtsPropsFor.PortraitFrame:
src: string;
  alt: string;
  className?: string;

dtsPropsFor.ProjectCard:
title: string;
  description: string;
  /** short tech/category labels, rendered dot-separated */
  categories: string[];
  href?: string;

dtsPropsFor.ExperienceItem:
/** 1-based position; rendered zero-padded (01, 02, ...) */
  index: number;
  role: string;
  org: string;
  date: string;
  summary: string;
  bullets: string[];
  tags: string[];
  /** render expanded on mount */
  defaultOpen?: boolean;

dtsPropsFor.EducationItem:
/** 1-based position; rendered zero-padded (01, 02, ...) */
  index: number;
  title: string;
  org: string;
  date: string;
  note: string;

dtsPropsFor.FounderCallout:
/** venture / product name, e.g. 'Seedfast' */
  name: string;
  href: string;
  /** bare domain shown on the right, e.g. 'seedfa.st' */
  url: string;
  description: string;
  /** pill label; defaults to 'Founder' */
  label?: string;
